select exists (select 1 from information_schema.columns where table_schema='public' and table_name='documents' and column_name='views') and exists (select 1 from information_schema.columns where table_schema='public' and table_name='documents' and column_name='downloads') and exists (select 1 from information_schema.columns where table_schema='public' and table_name='documents' and column_name='likes') and not exists (select 1 from pg_proc where pronamespace='public'::regnamespace and proname='increment_document_counter') as ok;
